import { QueryClient } from '@tanstack/react-query';

const MINUTE = 1000 * 60;

// v5: cacheTime renamed to gcTime (garbage collection time)
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      gcTime: 10 * MINUTE,  // how long to keep unused data
      staleTime: 5 * MINUTE, // how long data is considered fresh
    },
  },
});

