import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

// v5: onSuccess and onError removed from useQuery
// Use useEffect to respond to query state changes
function Todos() {
  const query = useQuery({ queryKey: ['todos'], queryFn: fetchTodos });

  useEffect(() => {
    if (query.isSuccess) {
      toast.success('Data loaded!');
    }
  }, [query.isSuccess]);

  useEffect(() => {
    if (query.isError) {
      toast.error(query.error.message);
    }
  }, [query.isError]);

  return query.data ? <TodoList todos={query.data} /> : null;
}

import { useQuery, useQueryClient } from '@tanstack/react-query';

function Profile() {
  const queryClient = useQueryClient();
  const query = useQuery({ queryKey: ['user'], queryFn: fetchUser });

  const handleLogout = () => {
    // v5: query.remove() is gone, use queryClient.removeQueries
    queryClient.removeQueries({ queryKey: ['user'] });
    // Also clear all queries if needed:
    // queryClient.clear();
  };

  return <button onClick={handleLogout}>Log out</button>;
}

import { useInfiniteQuery } from '@tanstack/react-query';

const { data, fetchNextPage, hasNextPage } = useInfiniteQuery({
  queryKey: ['items'],
  queryFn: ({ pageParam }) => fetchItems(pageParam), // no default value
  initialPageParam: 0, // required in v5
  getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined,
});

return (
  <div>
    {data?.pages.flatMap(page => page.items).map(item => <div key={item.id}>{item.name}</div>)}
    <button onClick={() => fetchNextPage()} disabled={!hasNextPage}>Load more</button>
  </div>
);

