import { HydrationBoundary, dehydrate, QueryClient } from '@tanstack/react-query';

export default async function Layout({ children }: { children: React.ReactNode }) {
  const queryClient = new QueryClient();
  await queryClient.prefetchQuery({ queryKey: ['todos'], queryFn: fetchTodos });

  return (
    // v5: Hydrate component renamed to HydrationBoundary
    <HydrationBoundary state={dehydrate(queryClient)}>
      {children}
    </HydrationBoundary>
  );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';

function AddTodo() {
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: createTodo,
    onSuccess: () => {
      // v5: object-only syntax for all queryClient methods
      queryClient.invalidateQueries({ queryKey: ['todos'] });
      // To invalidate all queries:
      queryClient.invalidateQueries();
    },
  });

  return <button onClick={() => mutation.mutate({ text: 'Buy milk' })}>Add</button>;
}

import { QueryClient, useQuery, QueryClientProvider } from '@tanstack/react-query';

// v5: pass a custom queryClient instance directly instead of context
const myQueryClient = new QueryClient();

function MyComponent() {
  const { data } = useQuery(
    { queryKey: ['todos'], queryFn: fetchTodos },
    myQueryClient  // pass queryClient as second argument
  );
  return <div>{data?.length} todos</div>;
}

// Or use a nested QueryClientProvider for full isolation:
function MicroFrontend() {
  return (
    <QueryClientProvider client={myQueryClient}>
      <MyComponent />
    </QueryClientProvider>
  );
}

