  const userData = queryClient.getQueryData(['user', { id: 1 }]);

  // For fuzzy matching use getQueriesData instead:
  const allUserQueries = queryClient.getQueriesData({ queryKey: ['user'] });

  return <div>{userData?.name}</div>;
